#!/usr/bin/env bash
# AgroMart — Live Prices MERGE: keeps YOUR LivePrice.jsx (upgraded), removes duplicates.
# Adds: live API data, trend arrows, role CTAs, visual weight flip.
# Run from ~/Documents/AgroMart:  bash apply_lp_merge.sh
set -euo pipefail
[ -d backend/src ] || { echo "ERROR: run from ~/Documents/AgroMart"; exit 1; }
say(){ echo "  $*"; }

echo "==> [1/5] Replacing frontend/src/pages/LivePrice.jsx with merged version..."
echo '' | base64 -d > frontend/src/pages/LivePrice.jsx && say 'wrote LivePrice.jsx'

echo "==> [2/5] Removing duplicate files (my old installer's + your dead backend route)..."
for f in frontend/src/pages/LivePrices.jsx \
         backend/src/routes/LivePrice.route.js; do
  if [ -f "$f" ]; then rm "$f" && say "deleted $f"; else say "$f already gone"; fi
done

echo "==> [3/5] Fixing frontend/src/App.jsx (remove duplicate route + import)..."
python3 - frontend/src/App.jsx << 'PY'
import sys,re
f=sys.argv[1]; s=open(f).read()
# remove the plural LivePrices import (mine)
s=re.sub(r"import LivePrices from '\./pages/LivePrices\.jsx';\n?", "", s)
# remove the plural LivePrices route
s=re.sub(r'\s*<Route path="/prices" element=\{<LivePrices\s*/>\}\s*/>\n?', "\n", s)
# ensure singular LivePrice route remains — collapse any accidental double newlines
s=re.sub(r'\n\n\n+', '\n\n', s)
open(f,'w').write(s)
print("  cleaned App.jsx")
PY

echo "==> [4/5] Adding i18n keys used by the upgraded LivePrice..."
python3 - frontend/src/i18n/strings.js << 'PY'
