def insert_missing(text, block, entries):
    # find "  block: {" then find matching closing "  },"
    m = __import__('re').search(r'(\b' + block + r'\s*:\s*\{)', text)
    if not m: return text, 0
    start = m.end()
    # find the matching '}' balancing braces
    depth = 1; i = start
    while i < len(text) and depth > 0:
        if text[i] == '{': depth += 1
        elif text[i] == '}': depth -= 1
        i += 1
    close = i - 1  # position of the '}'
    body = text[start:close]
    added = 0
    lines = []
    for k, v in entries.items():
        if f"{k}:" in body or f"'{k}'" in body or f'"{k}"' in body:
            continue
        # escape single quotes in value
        vv = v.replace("'", "\\'")
        lines.append(f"    {k}: '{vv}',")
        added += 1
    if not lines: return text, 0
    insert = ("\n" if not body.rstrip().endswith(',') and body.strip() else "") + "\n".join(lines) + "\n"
    return text[:close] + insert + text[close:], added

s, addA = insert_missing(s, 'bn', BASE_BN)
s, addB = insert_missing(s, 'en', BASE_EN)
open(f,'w').write(s)
print(f"  added {addA} bn keys, {addB} en keys (existing keys skipped)")
